<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use DigiForgePrintifyConnector\Preparation\{VersionedMutationHost,ProviderReceipt,PreparationService,MutationIntent,MutationFence};
require_once __DIR__.'/../fixtures/printify-connector/stage34/companion-test-bootstrap.php';
final class PrintifyCompanionMutationAdapterTest extends TestCase {
 private function intent():MutationIntent {require_once dirname(__DIR__,2).'/includes/Research/DesignFactoryContract.php';[$b,$e,$s]=(require __DIR__.'/../fixtures/printify-connector/stage34/artwork-fixture.php')();return (new PreparationService())->upload($s,$b,$e,['actor_id'=>1,'logical_reference'=>'core-asset-1','approval_reference'=>str_repeat('d',64),'authorization_revision'=>1,'product_version'=>1,'expected_product_version'=>0]);}
 private function core():object {require_once __DIR__.'/../fixtures/printify-connector/batch2/SyntheticMutationCore.php';return new SyntheticMutationCore();}
 public function testVersionedAdapterAndStrictReceiptContractExist():void {self::assertTrue(class_exists(VersionedMutationHost::class));self::assertTrue(class_exists(ProviderReceipt::class));}
 public function testMissingAndIncompatibleCoreDenyWithoutExchange():void {$i=$this->intent();self::assertInstanceOf(WP_Error::class,VersionedMutationHost::discover()->authorize($i));$c=$this->core();$c->version='9.0.0';self::assertInstanceOf(WP_Error::class,(new VersionedMutationHost($c))->register($i));self::assertSame(0,$c->calls);}
 public function testNegotiatedCoreRegistersAndFencesOnce():void {$i=$this->intent();$c=$this->core();$h=new VersionedMutationHost($c);$f=new MutationFence($h);self::assertIsArray($f->register($i));self::assertIsArray($f->reserve($i));self::assertInstanceOf(WP_Error::class,$f->reserve($i));self::assertSame('FENCED',$h->recover($i)['state']);self::assertFalse($h->recover($i)['network_request_permitted']);}
 /** @dataProvider invalidAuthority */
 public function testInvalidCoreAuthorityDeniesBeforeRegister(string $fault):void {$i=$this->intent();$c=$this->core();$c->fault=$fault;$h=new VersionedMutationHost($c);self::assertInstanceOf(WP_Error::class,(new MutationFence($h))->register($i));self::assertCount(0,$c->records);}
 public static function invalidAuthority():array {return array_map(static fn($x)=>[$x],['stop_all','external_lock','stale_approval','wrong_shop','wrong_credential','stale_version','expired','revoked','epoch_mismatch','audit_unavailable']);}
 public function testReceiptCommitsAndDuplicateIsIdempotent():void {$i=$this->intent();$c=$this->core();$h=new VersionedMutationHost($c);$f=new MutationFence($h);$f->register($i);$f->reserve($i);$r=$c->receipt($i);$a=$h->acceptReceipt($i,$r);self::assertSame('METADATA_RECONCILED',$a['state']);self::assertSame($a,$h->acceptReceipt($i,$r));self::assertSame(1,$c->receiptCount);self::assertInstanceOf(WP_Error::class,$f->reserve($i));self::assertFalse($a['network_request_permitted']);self::assertArrayNotHasKey('body',$a);}
 /** @dataProvider invalidReceipt */
 public function testTamperedOrMismatchedReceiptRejected(string $key,mixed $value):void {$i=$this->intent();$c=$this->core();$h=new VersionedMutationHost($c);$f=new MutationFence($h);$f->register($i);$f->reserve($i);$r=$c->receipt($i);$r[$key]=$value;$r['receipt_hash']=ProviderReceipt::hash($r);self::assertInstanceOf(WP_Error::class,$h->acceptReceipt($i,$r));self::assertSame(0,$c->receiptCount);}
 public static function invalidReceipt():array{return [['shop_key','standard_pod'],['provider_shop_id','wrong'],['operation_id',str_repeat('0',64)],['credential_reference',8],['authorization_revision',2],['approval_reference',str_repeat('0',64)],['http_status',429],['sequence',0],['body',[]],['unexpected','private-value'],['received_at',0],['kind','SENT']];}
 public function testReceiptHashTamperingRejected():void {$i=$this->intent();$c=$this->core();$r=$c->receipt($i);$r['body']['id']='tampered';$this->expectException(InvalidArgumentException::class);ProviderReceipt::validate($i,$r);}
 public function testOutOfOrderConflictingAndUnregisteredReceiptsDenied():void {$i=$this->intent();$c=$this->core();$h=new VersionedMutationHost($c);self::assertInstanceOf(WP_Error::class,$h->acceptReceipt($i,$c->receipt($i)));$f=new MutationFence($h);$f->register($i);$f->reserve($i);$r=$c->receipt($i);$late=$r;$late['sequence']=2;$late['receipt_hash']=ProviderReceipt::hash($late);self::assertInstanceOf(WP_Error::class,$h->acceptReceipt($i,$late));self::assertIsArray($h->acceptReceipt($i,$r));$r['body']['id']='conflicting';$r['receipt_hash']=ProviderReceipt::hash($r);self::assertInstanceOf(WP_Error::class,$h->acceptReceipt($i,$r));self::assertSame(1,$c->receiptCount);}
 public function testCancellationBeforeFenceAndAfterFenceCannotRearm():void {foreach([false,true]as $claimed){$i=$this->intent();$c=$this->core();$h=new VersionedMutationHost($c);$f=new MutationFence($h);$f->register($i);if($claimed)$f->reserve($i);self::assertSame($claimed?'UNKNOWN':'CANCELLED',$h->cancel($i)['state']);self::assertInstanceOf(WP_Error::class,$f->reserve($i));}}
 public function testCrashRecoveryNeverReleasesFenceAndUnknownCanReconcile():void {$i=$this->intent();$c=$this->core();$h=new VersionedMutationHost($c);$f=new MutationFence($h);$f->register($i);$f->reserve($i);$h=new VersionedMutationHost($c);self::assertSame('FENCED',$h->recover($i)['state']);self::assertTrue($h->outcome($i,'UNKNOWN',['operation_id'=>$i->operationId,'state'=>'UNKNOWN']));self::assertSame('UNKNOWN',$h->recover($i)['state']);self::assertInstanceOf(WP_Error::class,(new MutationFence($h))->reserve($i));self::assertSame('METADATA_RECONCILED',$h->acceptReceipt($i,$c->receipt($i))['state']);}
 public function testRestoredSnapshotDeniedAgainstIndependentCoreEpoch():void {$i=$this->intent();$c=$this->core();$h=new VersionedMutationHost($c);$f=new MutationFence($h);$f->register($i);$snapshot=$c->records;$c->advanceEpoch();$c->records=$snapshot;self::assertInstanceOf(WP_Error::class,$h->recover($i));self::assertInstanceOf(WP_Error::class,$f->reserve($i));}
 public function testRevokedCoreAndLostAcknowledgementNeverPermitRetry():void {foreach(['revoked','lost_claim_ack']as $fault){$i=$this->intent();$c=$this->core();$h=new VersionedMutationHost($c);$f=new MutationFence($h);$f->register($i);$c->fault=$fault;self::assertInstanceOf(WP_Error::class,$f->reserve($i));if($fault==='lost_claim_ack'){$c->fault='';self::assertInstanceOf(WP_Error::class,$f->reserve($i));self::assertSame('FENCED',$h->recover($i)['state']);}}}
 public function testLegacyFenceCanReconcileThroughVersionedAdapter():void {$i=$this->intent();$c=$this->core();$h=new VersionedMutationHost($c);$f=new MutationFence($h);$f->register($i);$f->reserve($i);$r=$c->receipt($i);$c->receipts[$r['receipt_hash']]=$r;self::assertSame('METADATA_RECONCILED',$f->reconcile($i,$r['receipt_hash'])['state']);}
 public function testUnknownReceiptRequiresNextSequenceForTerminalReconciliation():void {$i=$this->intent();$c=$this->core();$h=new VersionedMutationHost($c);$f=new MutationFence($h);$f->register($i);$f->reserve($i);$u=$c->receipt($i);$u['kind']='UNKNOWN';$u['http_status']=0;$u['body']=[];$u['receipt_hash']=ProviderReceipt::hash($u);self::assertSame('UNKNOWN',$h->acceptReceipt($i,$u)['state']);$terminal=$c->receipt($i);$terminal['event_id']=hash('sha256','terminal-event');self::assertInstanceOf(WP_Error::class,$h->acceptReceipt($i,$terminal));$terminal['sequence']=2;$terminal['receipt_hash']=ProviderReceipt::hash($terminal);self::assertSame('METADATA_RECONCILED',$h->acceptReceipt($i,$terminal)['state']);self::assertSame(2,$c->receiptCount);}
 public function testMissingProductCoreContractFailsClosed():void {self::assertInstanceOf(WP_Error::class,(new VersionedMutationHost())->recover($this->intent()));}
 public function testForgedJournalHashAndUnexpectedCoreFieldsRejected():void {$i=$this->intent();foreach(['journal_hash','unexpected_output']as $fault){$c=$this->core();$c->fault=$fault;$h=new VersionedMutationHost($c);self::assertInstanceOf(WP_Error::class,$h->authorize($i));}}
 public function testProductReceiptValidatesExactProviderIdentity():void {
  [$scope,$input,$e,$body]=(require __DIR__.'/../fixtures/printify-connector/stage34/product-fixture.php')();$i=(new PreparationService())->product('PRODUCT_CREATE',$scope,$input,$e,['actor_id'=>1,'logical_reference'=>'core-product-1','approval_reference'=>$e['approval_receipt_sha256'],'authorization_revision'=>7,'product_version'=>0,'expected_product_version'=>0]);$c=$this->core();$h=new VersionedMutationHost($c);$f=new MutationFence($h);$f->register($i);$f->reserve($i);$r=$c->receipt($i);self::assertSame('METADATA_RECONCILED',$h->acceptReceipt($i,$r)['state']);$r['body']['shop_id']=99003;$r['receipt_hash']=ProviderReceipt::hash($r);self::assertInstanceOf(WP_Error::class,$h->acceptReceipt($i,$r));
 }

 public function testRevocationDuringCoreCommitCannotProduceSuccessfulFenceAcknowledgement():void {$i=$this->intent();$c=$this->core();$h=new VersionedMutationHost($c);$f=new MutationFence($h);$f->register($i);$authority=$h->authorize($i);$c->fault='revoke_after_claim';self::assertInstanceOf(WP_Error::class,$h->claimOnce($i,$authority));$c->fault='';self::assertSame('FENCED',$h->recover($i)['state']);self::assertInstanceOf(WP_Error::class,$f->reserve($i));}

}
